#if UNITY_EDITOR
using Kamilunavo.RepairEmpire.Validation;
using UnityEditor;
using UnityEngine;
using UnityEngine.EventSystems;
using Kamilunavo.RepairEmpire.Input;
using Kamilunavo.RepairEmpire.Gameplay;
public static class RepairValidation {
 [MenuItem("Kamilunavo/Validate Repair Empire Rules")]
 public static void Run(){Debug.Log("REPAIR_EDITOR_RULE_PASS "+RepairRuleChecks.Run());Debug.Log("REPAIR_INTERACTION_EDITOR_PASS "+RepairInteractionChecks.Run());}
 public static void RunAndValidateInput(){Run();ValidateInput();}
 public static void ValidateInput(){
  var holdObject=new GameObject("RepairHoldFixture");var hold=holdObject.AddComponent<HoldButton>();
  try{hold.OnPointerDown(new PointerEventData(null));if(!hold.Held)throw new System.Exception("pointer down should hold");holdObject.SetActive(false);typeof(HoldButton).GetMethod("OnDisable",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)?.Invoke(hold,null);if(hold.Held)throw new System.Exception("REPAIR_INPUT_FAIL disabled button retains gas/steer");}finally{Object.DestroyImmediate(holdObject);}
  var car=new GameObject("RepairPauseFixture",typeof(Rigidbody),typeof(VehicleController));
  try{var motor=car.GetComponent<VehicleController>();motor.SendMessage("Awake");motor.InputEnabled=false;var body=car.GetComponent<Rigidbody>();body.linearVelocity=new Vector3(3,0,8);motor.SendMessage("FixedUpdate");if(body.linearVelocity.sqrMagnitude>.00001f)throw new System.Exception("REPAIR_INPUT_FAIL paused van keeps driving");}finally{Object.DestroyImmediate(car);}
  Debug.Log("REPAIR_INPUT_PASS held reset and stationary pause");
 }
 public static void ValidateRepairBoundary(){
  var root=new GameObject("RepairBoundaryFixture");root.SetActive(false);var game=root.AddComponent<RepairGame>();var car=new GameObject("BoundaryVan",typeof(Rigidbody),typeof(VehicleController));var motor=car.GetComponent<VehicleController>();motor.SendMessage("Awake");game.Vehicle=motor;game.Profile=new Kamilunavo.RepairEmpire.Core.RepairProfile();long ticket=Kamilunavo.RepairEmpire.Core.RepairRules.BeginJob(game.Profile,"faucet");
  try{car.transform.position=new Vector3(20,0,284);if(game.BeginRepair())throw new System.Exception("REPAIR_BOUNDARY_FAIL distant lateral repair");car.transform.position=new Vector3(5.5f,0,284);car.GetComponent<Rigidbody>().linearVelocity=Vector3.forward*5;if(game.BeginRepair())throw new System.Exception("REPAIR_BOUNDARY_FAIL moving repair");motor.ResetMotion();if(!game.BeginRepair()||!game.Paused)throw new System.Exception("REPAIR_BOUNDARY_FAIL stopped van repair modal");if(game.AdvanceRepair(2)||game.Profile.RepairPhase!=0||game.Profile.ActiveTicket!=ticket)throw new System.Exception("REPAIR_BOUNDARY_FAIL skipped phase");game.CloseRepair();if(game.Paused)throw new System.Exception("REPAIR_BOUNDARY_FAIL repair close keeps driving paused");Debug.Log("REPAIR_BOUNDARY_PASS lateral/speed/ordered stages/modal");}finally{Object.DestroyImmediate(root);Object.DestroyImmediate(car);}
 }
 public static void ConfigureAndValidateArt(){RepairArtImports.Ensure();ValidateArt();}
 public static void ValidateArt(){foreach(string key in new[]{"Art/RepairAtlas","Art/SkyPanorama","Art/WorldMaterialsAtlas","Art/TreeCanopy"})if(Resources.Load<Texture2D>(key)==null)throw new System.Exception("REPAIR_ART_FAIL missing Texture2D "+key);if(Resources.Load<Texture2DArray>("Art/WorldSurfaceArray")==null)throw new System.Exception("REPAIR_ART_FAIL missing isolated city texture layers");if(Resources.Load<Shader>("CitySurface")==null)throw new System.Exception("REPAIR_ART_FAIL missing textured city shader");var root=new GameObject("VanArtFixture");try{var art=root.AddComponent<Kamilunavo.RepairEmpire.Visuals.VanArt>();art.Build();foreach(var t in root.GetComponentsInChildren<TextMesh>()){var b=t.GetComponent<Renderer>().bounds;Debug.Log("REPAIR_TEXT_BOUNDS "+t.text+" "+b.size);if(b.size.x>1.2f)throw new System.Exception("REPAIR_ART_FAIL van branding exceeds rear doors "+t.text);}}finally{Object.DestroyImmediate(root);}var city=new GameObject("CityTextureFixture");try{city.AddComponent<CityBuilder>().Build();int count=0;foreach(var renderer in city.GetComponentsInChildren<MeshRenderer>())if(renderer.sharedMaterial.name=="CityAsphalt"){count++;if(renderer.sharedMaterial.shader.name!="Repair/CitySurface"||renderer.sharedMaterial.GetTexture("_CityTiles")!=Resources.Load<Texture2DArray>("Art/WorldSurfaceArray"))throw new System.Exception("REPAIR_ART_FAIL asphalt lacks real atlas binding");}if(count<3)throw new System.Exception("REPAIR_ART_FAIL missing textured avenues");}finally{Object.DestroyImmediate(city);}Debug.Log("REPAIR_ART_PASS loaded Texture2D, bounded van branding and actual textured avenues");}
 public static void ValidateHud(){
  var c=Kamilunavo.RepairEmpire.UI.UiFactory.CreateCanvas();var safe=Kamilunavo.RepairEmpire.UI.UiFactory.Panel(c.transform,"SafeFixture",Color.clear,Vector2.zero,Vector2.one);var root=new GameObject("HudGameFixture");root.SetActive(false);var game=root.AddComponent<RepairGame>();game.Profile=new Kamilunavo.RepairEmpire.Core.RepairProfile();Kamilunavo.RepairEmpire.Core.RepairRules.BeginJob(game.Profile,"faucet");var hud=safe.gameObject.AddComponent<Kamilunavo.RepairEmpire.UI.RepairHud>();Kamilunavo.RepairEmpire.UI.UiMetrics.QaPointScale=3;
  try{hud.Build(safe,game);Canvas.ForceUpdateCanvases();hud.Layout();Canvas.ForceUpdateCanvases();foreach(var hold in safe.GetComponentsInChildren<HoldButton>()){var r=Kamilunavo.RepairEmpire.UI.UiMetrics.ScreenRect((RectTransform)hold.transform);if(r.width/3<47.999f||r.height/3<47.999f)throw new System.Exception("REPAIR_HUD_FAIL small actual hold control "+hold.name);}hud.ShowPage(0);Canvas.ForceUpdateCanvases();if(!hud.ModalOpen||!game.Paused)throw new System.Exception("REPAIR_HUD_FAIL tablet doesn't pause driving");var close=GameObject.Find("Close");var rect=Kamilunavo.RepairEmpire.UI.UiMetrics.ScreenRect((RectTransform)close.transform);if(rect.width/3<47.999f||rect.height/3<47.999f)throw new System.Exception("REPAIR_HUD_FAIL close below48points");var scroll=safe.GetComponentInChildren<UnityEngine.UI.ScrollRect>();if(scroll==null||!scroll.viewport.GetComponent<UnityEngine.UI.Image>().raycastTarget)throw new System.Exception("REPAIR_HUD_FAIL job notes cannot receive scroll");hud.Close();if(game.Paused)throw new System.Exception("REPAIR_HUD_FAIL closed tablet leaves input paused");Debug.Log("REPAIR_HUD_PASS actual minimum controls/modal/scroll binding");}finally{Kamilunavo.RepairEmpire.UI.UiMetrics.QaPointScale=null;Object.DestroyImmediate(c.gameObject);Object.DestroyImmediate(root);}
 }
}
#endif
